-- MANUAL RECOVERY ONLY, if the matching Master Sales cleanup was committed.
-- Run in PRODUCTION only, as a single script with stop-on-error enabled.
-- If an error occurs before COMMIT, issue ROLLBACK. If COMMIT succeeds but
-- ENABLE TRIGGER fails, run that ENABLE TRIGGER line immediately.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
LOCK TABLE journal_entries, journal_entry_lines, journal_entry_audit IN ACCESS EXCLUSIVE MODE;
CREATE TEMP TABLE master_sales_restore_payload ON COMMIT DROP AS
 SELECT convert_from(decode('','base64'),'UTF8')::jsonb AS data;
DO $guard$
DECLARE backup jsonb;
BEGIN
 SELECT data INTO backup FROM master_sales_restore_payload;
 IF backup->>'file_fingerprint' <> 'ff316fd33b56c91c4a383043'
    OR jsonb_array_length(backup->'journal_entries') <> 82
    OR jsonb_array_length(backup->'journal_entry_lines') <> 246
    OR jsonb_array_length(backup->'journal_entry_audit') <> 82
    OR (SELECT md5(string_agg(x->>'id'||':'||x->>'source_id', E'\n' ORDER BY (x->>'id')::integer))
          FROM jsonb_array_elements(backup->'journal_entries') AS x)
        <> '4c187b5979e2469f9682d060f5bdeab4' THEN
   RAISE EXCEPTION 'Backup identity or row counts changed; nothing restored';
 END IF;
 IF EXISTS(SELECT 1 FROM journal_entries
            WHERE source_type='historical_import' AND source_id LIKE 'ff316fd33b56c91c4a383043:%')
    OR EXISTS(SELECT 1 FROM journal_entries e
               WHERE e.id IN (SELECT (x->>'id')::integer FROM jsonb_array_elements(backup->'journal_entries') x)
                  OR e.entry_number IN (SELECT x->>'entry_number' FROM jsonb_array_elements(backup->'journal_entries') x))
    OR EXISTS(SELECT 1 FROM journal_entry_lines l
               WHERE l.id IN (SELECT (x->>'id')::integer FROM jsonb_array_elements(backup->'journal_entry_lines') x))
    OR EXISTS(SELECT 1 FROM journal_entry_audit a
               WHERE a.id IN (SELECT (x->>'id')::integer FROM jsonb_array_elements(backup->'journal_entry_audit') x)) THEN
   RAISE EXCEPTION 'Conflicting journal or dependent IDs exist; nothing restored';
 END IF;
 IF (SELECT count(*) FROM pg_trigger
       WHERE tgname IN ('journal_entries_immutable','journal_entry_lines_immutable',
                        'journal_entries_balanced','journal_entry_lines_balanced')
         AND tgenabled='O') <> 4 THEN
   RAISE EXCEPTION 'Accounting protection triggers are not enabled; nothing restored';
 END IF;
END $guard$;
ALTER TABLE journal_entry_lines DISABLE TRIGGER journal_entry_lines_immutable;
INSERT INTO journal_entries
 SELECT * FROM jsonb_populate_recordset(NULL::journal_entries,
   (SELECT data->'journal_entries' FROM master_sales_restore_payload));
INSERT INTO journal_entry_lines
 SELECT * FROM jsonb_populate_recordset(NULL::journal_entry_lines,
   (SELECT data->'journal_entry_lines' FROM master_sales_restore_payload));
INSERT INTO journal_entry_audit
 SELECT * FROM jsonb_populate_recordset(NULL::journal_entry_audit,
   (SELECT data->'journal_entry_audit' FROM master_sales_restore_payload));
DO $check$
BEGIN
 IF (SELECT count(*) FROM journal_entries WHERE source_type='historical_import'
     AND source_id LIKE 'ff316fd33b56c91c4a383043:%') <> 82
    OR (SELECT count(*) FROM journal_entry_lines WHERE journal_entry_id IN
       (SELECT id FROM journal_entries WHERE source_type='historical_import'
        AND source_id LIKE 'ff316fd33b56c91c4a383043:%')) <> 246
    OR (SELECT count(*) FROM journal_entry_audit WHERE journal_entry_id IN
       (SELECT id FROM journal_entries WHERE source_type='historical_import'
        AND source_id LIKE 'ff316fd33b56c91c4a383043:%')) <> 82 THEN
   RAISE EXCEPTION 'Restoration verification failed; transaction will roll back';
 END IF;
END $check$;
COMMIT;
ALTER TABLE journal_entry_lines ENABLE TRIGGER journal_entry_lines_immutable;
SELECT tgname,tgenabled FROM pg_trigger
 WHERE tgname IN ('journal_entries_immutable','journal_entry_lines_immutable') ORDER BY tgname;
